WITH base AS (SELECT id, supplier_name, country, city, rating, SUBSTRING(supplier_name, 1, 4) AS supplier_name_prefix FROM suppliers WHERE rating BETWEEN 2.0 AND 3.7) SELECT id, country, city, rating, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) AS rating_share, AVG(rating) OVER (ORDER BY rating, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS rating_avg_5_prior FROM base;
